def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def edge_run(row):
        # This task has one colored horizontal segment at each opposite edge.
        best = None
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color, start = row[c], c
            while c < w and row[c] == color:
                c += 1
            if best is None or c - start > best[2]:
                best = (color, start, c - start)
        return best

    top = edge_run(grid[0])
    bottom = edge_run(grid[-1])
    if not top or not bottom or top[0] != bottom[0] or top[2] != bottom[2]:
        return [row[:] for row in grid]
    bar_color, top_start, width = top
    _, bottom_start, _ = bottom

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != bar_color]
    if not markers:
        return [row[:] for row in grid]
    fill_color = Counter(v for _, _, v in markers).most_common(1)[0][0]

    # Markers activate a lane by their offset along either edge bar.
    active = set()
    for _, c, _ in markers:
        if bottom_start <= c < bottom_start + width:
            active.add(c - bottom_start)
        if top_start <= c < top_start + width:
            active.add(c - top_start)

    out = [row[:] for row in grid]
    for r, c, _ in markers:
        out[r][c] = 4

    # Both bars emit the marker color along each activated lane, stopping at
    # the first marker encountered. Existing bars remain unchanged.
    for offset in active:
        for start, direction in ((top_start, 1), (bottom_start, -1)):
            c = start + offset
            r = 1 if direction == 1 else h - 2
            while 0 <= r < h:
                if grid[r][c] != bg:
                    if grid[r][c] != bar_color:
                        out[r][c] = 4
                    break
                out[r][c] = fill_color
                r += direction
    return out
